INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Kommunikations-Modelle > Lasswell-Formel
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Beschreibt die Lasswell-Formel Kommunikation als einen linearen Prozess mit fünf Fragen?', 2, '[{"text": "Ja", "correct": true, "because": "Wer sagt was, in welchem Kanal, zu wem, mit welcher Wirkung"}, {"text": "Nein", "correct": false, "because": "Das Modell basiert auf diesen fünf Elementen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Lasswell-Formel helfen, die Wirkung einer Kommunikation zu analysieren?', 2, '[{"text": "Ja", "correct": true, "because": "Die Wirkung ist eine der fünf Fragen"}, {"text": "Nein", "correct": false, "because": "Wirkung ist zentraler Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Lasswell-Formel auf technische Kommunikation beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Sie ist allgemein auf Kommunikation anwendbar"}, {"text": "Ja", "correct": false, "because": "Nicht auf Technik beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Störungen im Kanal laut Lasswell-Formel die Kommunikation beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Der Kanal ist entscheidend für die Übertragung"}, {"text": "Nein", "correct": false, "because": "Störungen wirken sich aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Berücksichtigt die Lasswell-Formel Rückmeldungen vom Empfänger?', 2, '[{"text": "Nein", "correct": true, "because": "Das Modell ist linear ohne Feedback"}, {"text": "Ja", "correct": false, "because": "Rückkopplung ist nicht enthalten"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Frage der Lasswell-Formel bezieht sich auf die Quelle der Nachricht?', 3, '[{"text": "Wer?", "correct": true, "because": "Fragt nach dem Sender"}, {"text": "Zu wem?", "correct": false, "because": "Fragt nach dem Empfänger"}, {"text": "Mit welcher Wirkung?", "correct": false, "because": "Fragt nach dem Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element der Lasswell-Formel beschreibt das Medium der Kommunikation?', 2, '[{"text": "In welchem Kanal?", "correct": true, "because": "Bezieht sich auf das Übertragungsmedium"}, {"text": "Was?", "correct": false, "because": "Bezieht sich auf den Inhalt"}, {"text": "Zu wem?", "correct": false, "because": "Bezieht sich auf den Empfänger"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Lasswell-Formel?', 2, '[{"text": "Analyse des Kommunikationsprozesses", "correct": true, "because": "Zerlegt Kommunikation in fünf Fragen"}, {"text": "Emotionale Verbindung fördern", "correct": false, "because": "Nicht das Ziel"}, {"text": "Technische Fehler beheben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann laut Lasswell-Formel entstehen, wenn der Kanal gestört ist?', 3, '[{"text": "Missverständnisse beim Empfänger", "correct": true, "because": "Störungen verzerren die Nachricht"}, {"text": "Schnellere Übertragung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Korrektur", "correct": false, "because": "Nicht vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frage der Lasswell-Formel untersucht den Inhalt der Kommunikation?', 2, '[{"text": "Was?", "correct": true, "because": "Fragt nach der Nachricht selbst"}, {"text": "Wer?", "correct": false, "because": "Fragt nach dem Sender"}, {"text": "Mit welcher Wirkung?", "correct": false, "because": "Fragt nach dem Ergebnis"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Lasswell-Formel?', 4, '[{"text": "Wer?", "correct": true, "because": "Sender"}, {"text": "In welchem Kanal?", "correct": true, "because": "Medium"}, {"text": "Zu wem?", "correct": true, "because": "Empfänger"}, {"text": "Emotionen", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fragen der Lasswell-Formel analysieren die Kommunikation?', 3, '[{"text": "Was?", "correct": true, "because": "Inhalt der Nachricht"}, {"text": "Mit welcher Wirkung?", "correct": true, "because": "Ergebnis der Kommunikation"}, {"text": "In welchem Kanal?", "correct": true, "because": "Übertragungsweg"}, {"text": "Warum?", "correct": false, "because": "Nicht Teil der Formel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Kommunikation deckt die Lasswell-Formel ab?', 4, '[{"text": "Quelle", "correct": true, "because": "Wer?"}, {"text": "Inhalt", "correct": true, "because": "Was?"}, {"text": "Ziel", "correct": true, "because": "Zu wem?"}, {"text": "Rückkopplung", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann die Lasswell-Formel identifizieren?', 3, '[{"text": "Unklarer Sender", "correct": true, "because": "Wer-Frage unklar"}, {"text": "Gestörter Kanal", "correct": true, "because": "Kanalprobleme"}, {"text": "Unzureichende Wirkung", "correct": true, "because": "Wirkung unklar"}, {"text": "Emotionale Missverständnisse", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Lasswell-Formel?', 3, '[{"text": "Strukturierte Analyse", "correct": true, "because": "Zerlegt Kommunikation"}, {"text": "Identifikation von Schwachstellen", "correct": true, "because": "Zeigt Problemstellen"}, {"text": "Einfache Anwendung", "correct": true, "because": "Klar definierte Fragen"}, {"text": "Förderung von Empathie", "correct": false, "because": "Nicht das Ziel"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Lasswell-Formel fragt nach dem Sender mit „Wer?“. b) Sie berücksichtigt Rückmeldungen vom Empfänger.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wer ja, Rückmeldung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) „Mit welcher Wirkung?“ analysiert das Ergebnis der Kommunikation. b) Die Lasswell-Formel ist ein zirkuläres Modell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wirkung ja, linear nicht zirkulär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Kanal ist ein zentraler Bestandteil der Lasswell-Formel. b) Emotionen sind eine der fünf Fragen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kanal ja, Emotionen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Lasswell-Formel kann Kommunikationsprobleme analysieren. b) Sie wurde ursprünglich für menschliche Interaktion entwickelt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Analyse ja, Massenkommunikation Ursprung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) „Zu wem?“ fragt nach dem Empfänger in der Lasswell-Formel. b) Das Modell ist ausschließlich technisch orientiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Empfänger ja, allgemein anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

